/* Minimal `ws`-compatible WebSocket client for the integration harness.
 *
 * The NodeCG extension requires the `ws` package, which is not installed
 * on this VM (and the harness must not npm-install anything). Node 24
 * ships a built-in WebSocket client, so this shim wraps it in the small
 * event-emitter API the extension uses:
 *
 *   const WebSocket = require('ws');
 *   const ws = new WebSocket(url);
 *   ws.on('open' | 'message' | 'close' | 'error', handler);
 *   ws.send(string);
 *
 * Message payloads arrive as Buffers, matching the real `ws` behaviour
 * (the extension calls raw.toString() on them). This is test tooling
 * only — never a production dependency.
 */
'use strict';

const { EventEmitter } = require('events');

class WebSocket extends EventEmitter {
  constructor(url, protocols) {
    super();
    this.url = url;
    this.readyState = WebSocket.CONNECTING;
    this._ws = new globalThis.WebSocket(url, protocols);
    this._ws.addEventListener('open', () => {
      this.readyState = WebSocket.OPEN;
      this.emit('open');
    });
    this._ws.addEventListener('message', (ev) => {
      const data = typeof ev.data === 'string'
        ? Buffer.from(ev.data, 'utf8')
        : Buffer.from(ev.data);
      this.emit('message', data);
    });
    this._ws.addEventListener('close', (ev) => {
      this.readyState = WebSocket.CLOSED;
      this.emit('close', ev.code, ev.reason);
    });
    this._ws.addEventListener('error', (ev) => {
      const err = ev instanceof Error ? ev : new Error(`WebSocket error: ${ev.message || 'unknown'}`);
      this.emit('error', err);
    });
  }

  send(data, cb) {
    try {
      this._ws.send(data);
      if (typeof cb === 'function') cb();
    } catch (err) {
      if (typeof cb === 'function') cb(err);
      else throw err;
    }
  }

  close(code, reason) {
    this._ws.close(code, reason);
  }

  terminate() {
    this._ws.close();
  }
}

WebSocket.CONNECTING = 0;
WebSocket.OPEN = 1;
WebSocket.CLOSING = 2;
WebSocket.CLOSED = 3;

module.exports = WebSocket;
